import multiprocessing as mp


def 求和(篮子, 编号, 数):
    小计 = 0
    for k in range(1, 数 + 1):
        小计 += k
    篮子.put((编号, 小计))


if __name__ == '__main__':
    n = {n}
    起点 = []
    for _ in range(n):
        起点.append(int(input()))
    篮子 = mp.Queue()
    孩子们 = []
    for i in range(n):
        p = mp.Process(target=求和, args=(篮子, i + 1, 起点[i]))
        p.start()
        孩子们.append(p)
    收成 = []
    for _ in range(n):
        收成.append(篮子.get())
    for p in 孩子们:
        p.join()
    收成.sort()
    for 编号, 小计 in 收成:
        print("第 " + str(编号) + " 只：" + str(小计))
